// 나쁨: 프로세스 메모리 (그 서버에만)
const sessions = new Map();
sessions.set(sid, user);

// 좋음: 공용 저장소 (모든 서버가 공유)
await redis.set(`session:${sid}`, JSON.stringify(user), 'EX', 3600);

// 상태별 밖으로:
//  세션 → Redis·JWT   파일 → S3   캐시 → Redis
//  진행 작업 → 큐·DB   스케줄러 → 리더선출   웹소켓 → 브로커

app.get('/livez', (_, res) => res.send('ok'));  // 프로세스 살아 있나(가볍게)

app.get('/readyz', async (_, res) => {           // 요청 받을 준비 됐나
  // 시작 완료·워밍업 됐나 정도만. DB 확인은 신중히!
  if (!appReady) return res.status(503).send('starting');
  res.send('ok');
});
// ★ readiness 에 DB 를 넣으면: DB 가 잠깐 흔들릴 때
//   모든 인스턴스가 동시에 readyz 실패 → 전부 트래픽 제외 → 전체 중단

let ready = true;
app.get('/readyz', (_, res) => ready ? res.send('ok') : res.status(503).end());

process.on('SIGTERM', async () => {
  ready = false;                 // ① readyz 실패 → LB 가 이 서버로 새 요청 안 보냄
  await sleep(5000);             //    LB 가 뺄 시간(전파 지연) 기다림
  server.close(async () => {     // ② 진행 중 요청 완료 후 닫힘(드레이닝)
    await db.end();              // ③ 자원 정리
    process.exit(0);
  });
});
// 유예(grace period) 안에 끝내야 SIGKILL 안 당함(sys-signal)
